#include <stdio.h>
#include <stdlib.h>

int main() {
    int *arr = malloc(5 * sizeof(int));
    int *temp = realloc(arr, 10 * sizeof(int));
    if (temp == NULL) {
        printf("Reallocation failed\n");
        free(arr);
        return 1;
    }
    arr = temp;
    arr[9] = 42;
    printf("%d\n", arr[9]);
    free(arr);
    return 0;
}
